import multiprocessing as mp


def 平方(篮子, 数):
    篮子.append(数 * 数)


def 主流程():
    起点 = []
    for _ in range({k}):
        起点.append(int(input()))
    篮子 = mp.Manager().list()
    孩子们 = []
    for i in range({k}):
        p = mp.Process(target=平方, args=(篮子, 起点[i]))
        p.start()
        孩子们.append(p)
    for p in 孩子们:
        p.join()
    print(sum(篮子))


if __name__ == '__main__':
    主流程()
